var paths=UnityEditor.AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/TomatoStages"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).ToArray();var ms=paths.Select(UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>).SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).SelectMany(r=>r.sharedMaterials).Where(m=>m!=null).Distinct();return ms.Select(m=>new{name=m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),shader=m.shader.name,queue=m.renderQueue,keywords=m.shaderKeywords,alpha=m.HasProperty("_Surface")?m.GetFloat("_Surface"):-1,mode=m.HasProperty("_Mode")?m.GetFloat("_Mode"):-1,tex=m.HasProperty("_BaseMap")?UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap")):UnityEditor.AssetDatabase.GetAssetPath(m.mainTexture)}).ToArray();
